<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller;use App\Models\News;use Illuminate\Http\Request;use Illuminate\Support\Facades\Storage;use Illuminate\Support\Str;
class NewsController extends Controller{public function index(){return News::whereNotNull('published_at')->where('published_at','<=',now())->with('author:id,name')->orderByDesc('featured')->orderByDesc('pinned')->orderByDesc('published_at')->paginate(12);}public function show(News $article){abort_unless($article->published_at&&$article->published_at->lte(now()),404);return $article->load('author:id,name');}public function adminIndex(){return News::with('author:id,name')->orderByDesc('created_at')->paginate(30);}public function store(Request $request){$data=$this->validated($request);$data['slug']=$this->uniqueSlug($data['title']);$data['created_by']=$request->user()->id;$data['published_at']=$request->boolean('published')?($data['published_at']??now()):null;if($request->hasFile('image'))$data['image_url']=$this->storeImage($request);if($data['featured']??false)News::query()->update(['featured'=>false]);unset($data['published']);return response()->json(News::create($data),201);}public function update(Request $request,News $article){$data=$this->validated($request,true);if(isset($data['title'])&&$data['title']!==$article->title)$data['slug']=$this->uniqueSlug($data['title'],$article->id);if($request->hasFile('image')){$this->deleteLocalImage($article->image_url);$data['image_url']=$this->storeImage($request);}if($request->has('published'))$data['published_at']=$request->boolean('published')?($data['published_at']??$article->published_at??now()):null;if($data['featured']??false)News::where('id','!=',$article->id)->update(['featured'=>false]);unset($data['published']);$article->update($data);return $article->fresh();}public function destroy(News $article){$this->deleteLocalImage($article->image_url);$article->delete();return response()->json(['message'=>'Article deleted.']);}private function validated(Request $request,bool $partial=false):array{$r=$partial?'sometimes':'required';return $request->validate(['title'=>"$r|string|max:180",'category'=>'sometimes|string|max:100','excerpt'=>'nullable|string|max:500','body'=>"$r|string|max:50000",'pinned'=>'sometimes|boolean','featured'=>'sometimes|boolean','published'=>'sometimes|boolean','published_at'=>'nullable|date','image'=>'sometimes|image|mimes:jpeg,jpg,png,webp|max:10240']);}private function uniqueSlug(string $title,?int $ignore=null):string{$base=Str::slug($title);$slug=$base;$i=2;while(News::where('slug',$slug)->when($ignore,fn($q)=>$q->where('id','!=',$ignore))->exists())$slug=$base.'-'.$i++;return $slug;}private function storeImage(Request $request):string{return Storage::disk('public')->url($request->file('image')->store('news','public'));}private function deleteLocalImage(?string $url):void{if($url&&str_contains($url,'/storage/'))Storage::disk('public')->delete(str($url)->after('/storage/')->toString());}}
